21	function encodeQuery(params) {
22	  const parts = []
23	  Object.keys(params).forEach((key) => {
24	    const value = params[key]
25	    if (value !== "" && value !== undefined && value !== null) {
26	      parts.push(encodeURIComponent(key) + "=" + encodeURIComponent(value))
27	    }
28	  })
29	  return parts.join("&")
30	}
