43	function request(options) {
44	  const url = options.url
45	  const method = options.method || "GET"
46	  const responseType = options.responseType || "json"
47	  
48	  console.info("[InfoPlat] >>> Request [" + method + "]: " + url)
49	  
50	  return new Promise((resolve, reject) => {
51	    let isCompleted = false
52	    
53	    // Set a manual 60s timeout
54	    const timeoutId = setTimeout(() => {
55	      if (!isCompleted) {
56	        isCompleted = true
57	        console.error("[InfoPlat] !!! Request Timeout (60s): " + url)
58	        reject(new Error("Timeout"))
59	      }
60	    }, 60000)
61	
62	    fetch.fetch({
63	      url: url,
64	      method: method,
65	      header: options.header || {},
66	      responseType: responseType,
67	      success(res) {
68	        if (isCompleted) return
69	        isCompleted = true
70	        clearTimeout(timeoutId)
71	
72	        const code = res.code || res.statusCode
73	        console.info("[InfoPlat] <<< Response Code: " + code + " for " + url)
74	        
75	        let data = res.data
76	        if (responseType === "json" && typeof data === "string") {
77	          data = parseData(data)
78	        }
79	
80	        if (code >= 200 && code < 300) {
81	          resolve(data)
82	        } else {
83	          console.error("[InfoPlat] !!! Request HTTP Error: " + code + " Data: " + JSON.stringify(data))
84	          reject(new Error("HTTP " + code))
85	        }
86	      },
87	      fail(data, code) {
88	        if (isCompleted) return
89	        isCompleted = true
90	        clearTimeout(timeoutId)
91	        
92	        console.error("[InfoPlat] !!! Request Failed: Code " + code + " Msg: " + data)
93	        reject(new Error("Fetch failed: " + code))
94	      }
95	    })
96	  })
97	}
