110	function stripHtmlAndFilter(text) {
111	  if (!text) return ""
112	  // Reduced logging here to avoid flooding, but keeping the core filter
113	  let cleanText = text.replace(/<[^>]+>/g, " ")
114	  cleanText = cleanText.replace(/&nbsp;/g, " ")
115	                       .replace(/&quot;/g, "\"")
116	                       .replace(/&amp;/g, "&")
117	                       .replace(/&lt;/g, "<")
118	                       .replace(/&gt;/g, ">")
119	
120	  let lines = cleanText.split(/[\r\n]+/)
121	  let filteredLines = lines.filter((line) => line.indexOf("⬅️") === -1)
122	  
123	  return filteredLines.join("\n").trim()
124	}
