140	export function getLatestNews(options) {
141	  const params = options || {}
142	  // Join categories if it's an array, otherwise default to general
143	  const categories = params.categories && params.categories.length ? params.categories.join(",") : "general"
144	  
145	  const query = encodeQuery({
146	    language: "zh",
147	    country: "CN",
148	    category: categories,
149	    page_size: params.pageSize || 20,
150	    apiKey: CURRENTS_API_KEY.trim()
151	  })
152	
153	  return request({
154	    url: CURRENTS_BASE_URL + "/latest-news?" + query
155	  }).then((data) => {
156	    if (!data || data.status !== "ok" || !data.news) {
157	      console.error("[InfoPlat] News data status not ok: " + (data ? data.status : "null"))
158	      return []
159	    }
160	    return data.news.map(normalizeNews).filter(i => i !== null)
161	  })
162	}
