// 2. Extract nested content: find opening tag, then count div depth to find matching close
function extractNested(html, openPattern) {
  let openMatch = openPattern.exec(html)
  if (!openMatch) return null
  let openEnd = openMatch.index + openMatch[0].length
  let depth = 1
  let pos = openEnd
  while (depth > 0 && pos < html.length) {
    let nextOpen = html.indexOf("<div", pos)
    let nextClose = html.indexOf("</div>", pos)
    // Also handle <article> / <main> closers
    let nextArticleClose = html.indexOf("</article>", pos)
    let nextMainClose = html.indexOf("</main>", pos)

    let candidates = []
    if (nextOpen !== -1) candidates.push({ pos: nextOpen, type: "open" })
    if (nextClose !== -1) candidates.push({ pos: nextClose, type: "close-div" })
    if (nextArticleClose !== -1) candidates.push({ pos: nextArticleClose, type: "close-article" })
    if (nextMainClose !== -1) candidates.push({ pos: nextMainClose, type: "close-main" })

    if (candidates.length === 0) break
    candidates.sort(function(a, b) { return a.pos - b.pos })
    let first = candidates[0]

    if (first.type === "open") {
      depth++
      pos = first.pos + 4
    } else {
      depth--
      if (depth === 0) {
        return html.substring(openEnd, first.pos)
      }
      pos = first.pos + 6
    }
  }
  // If we ran out of HTML with depth > 0, return everything after opening tag
  return html.substring(openEnd)
}

