// 2. Extract nested content: find opening tag, then count div depth to find matching close
function extractNested(html, openPattern, label) {
  let openMatch = openPattern.exec(html)
  if (!openMatch) {
    console.log("[Parse] Container '" + label + "' NOT FOUND")
    return null
  }
  let openEnd = openMatch.index + openMatch[0].length
  let depth = 1
  let pos = openEnd
  let openCount = 0
  let closeCount = 0
  while (depth > 0 && pos < html.length) {
    let nextOpen = html.indexOf("<div", pos)
    let nextClose = html.indexOf("</div>", pos)

    let candidates = []
    if (nextOpen !== -1) candidates.push({ pos: nextOpen, type: "open" })
    if (nextClose !== -1) candidates.push({ pos: nextClose, type: "close" })

    if (candidates.length === 0) break
    candidates.sort(function(a, b) { return a.pos - b.pos })
    let first = candidates[0]

    if (first.type === "open") {
      depth++
      openCount++
      pos = first.pos + 4
    } else {
      depth--
      closeCount++
      if (depth === 0) {
        let extracted = html.substring(openEnd, first.pos)
        console.log("[Parse] Container '" + label + "' FOUND: depth opened=" + openCount + " closed=" + closeCount + " extracted=" + extracted.length)
