export function getLatestNews(options) {
  const params = options || {}
  const isTrending = !params.categories || params.categories.length === 0
  const categories = params.categories && params.categories.length ? params.categories.join(",") : ""

  // Use /top-news for general (trending across all categories),
  // use /latest-news for specific category filters
  let url
  if (isTrending) {
    const query = encodeQuery({
      language: "zh",
      country: "CN",
      page_size: params.pageSize || 20,
      apiKey: CURRENTS_API_KEY.trim()
    })
    url = CURRENTS_BASE_URL + "/top-news?" + query
  } else {
    const query = encodeQuery({
      language: "zh",
      country: "CN",
      category: categories,
      page_size: params.pageSize || 20,
      apiKey: CURRENTS_API_KEY.trim()
    })
    url = CURRENTS_BASE_URL + "/latest-news?" + query
  }

  console.info("[InfoPlat] News request: " + (isTrending ? "trending" : "category=" + categories))

  return request({
    url: url
  }).then((data) => {
    if (!data || data.status !== "ok" || !data.news) {
      console.error("[InfoPlat] News data status not ok: " + (data ? data.status : "null"))
      return []
    }
    return data.news.map(normalizeNews).filter(i => i !== null)
  })
}

